    "default_html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Question Paper</title>\n    <script src=\"https://polyfill.io/v3/polyfill.min.js?features=es6\"></script>\n    <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\n    <style>\n        :root {\n            --primary-dark: #464646;\n            --primary-light: #ffffff;\n            --primary-gradient: linear-gradient(to right, #000000, #000000);\n            --text-main: #333333;\n            --text-muted: #666666;\n            --border-color: #e0e0e0;\n        }\n        body {\n            font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            color: var(--text-main);\n            margin: 0;\n            padding: 20px;\n        }\n        .page {\n            width: 100%;\n            position: relative;\n            overflow: hidden;\n            border-radius: 4px;\n        }\n        .page::before {\n            content: '';\n            position: absolute;\n            top: 0; right: 0;\n            width: 50%; height: 120px;\n            background: linear-gradient(135deg, transparent 40%, rgba(91, 163, 224, 0.1) 100%);\n            border-bottom-left-radius: 100%;\n            pointer-events: none;\n            z-index: 0;\n        }\n        .content-wrapper {\n            position: relative;\n            z-index: 1;\n        }\n        .top-header {\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            margin-bottom: 30px;\n        }\n        .logo-area img {\n            height: 80px;\n        }\n        .main-title-container {\n            text-align: center;\n            margin-bottom: 25px;\n        }\n        .sub-title {\n            font-size: 16px;\n            color: var(--text-muted);\n            font-weight: 600;\n            letter-spacing: 0.5px;\n        }\n        .meta-bar {\n            background: #000;\n            color: white;\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            padding: 12px 25px;\n            border-radius: 6px;\n            font-size: 13.5px;\n            font-weight: 600;\n            margin-bottom: 40px;\n        }\n        .meta-item { display: flex; align-items: center; }\n        .meta-divider {\n            width: 1px;\n            height: 16px;\n            background-color: rgba(255,255,255,0.3);\n            margin: 0 15px;\n        }\n        .meta-label {\n            color: #ffffff;\n            margin-right: 6px;\n            font-weight: normal;\n        }\n        .section-container {\n            margin-bottom: 30px;\n            border-radius: 8px 8px 0 0;\n            overflow: hidden;\n            background-color: #fafbfc;\n        }\n        .section-header-bar {\n            display: flex;\n            background: var(--primary-gradient);\n            color: white;\n            position: relative;\n        }\n        .section-badge-wrapper {\n            background-color: var(--primary-dark);\n            padding: 10px 30px 10px 20px;\n            font-weight: bold;\n            font-size: 16px;\n            clip-path: polygon(0 0, 100% 0, 85% 100%, 0% 100%);\n            min-width: 130px;\n            display: flex;\n            align-items: center;\n            z-index: 2;\n        }\n        .section-title-wrapper {\n            padding: 10px 20px;\n            font-weight: 800;\n            font-style: italic;\n            letter-spacing: 0.5px;\n            display: flex;\n            align-items: center;\n            text-transform: uppercase;\n            font-size: 15px;\n            z-index: 1;\n            margin-left: -15px;\n        }\n        .section-instruction {\n            background-color: #f0f5fa;\n            color: #444;\n            font-size: 13.5px;\n            padding: 10px 20px;\n            border-bottom: 1px solid var(--border-color);\n        }\n        .questions-list {\n            background-color: white;\n            border-radius: 0 0 8px 8px;\n        }\n        .question-row {\n            display: flex;\n            padding: 16px 20px;\n            border-bottom: 1px solid var(--border-color);\n            font-size: 14.5px;\n            line-height: 1.6;\n        }\n        .question-row:last-child { border-bottom: none; }\n        .question-num {\n            font-weight: bold;\n            width: 35px;\n            flex-shrink: 0;\n            color: var(--primary-dark);\n        }\n        .question-text { flex-grow: 1; padding-right: 20px; }\n        .question-mark {\n            font-weight: 600;\n            color: var(--text-muted);\n            width: 50px;\n            text-align: right;\n            flex-shrink: 0;\n            font-size: 13px;\n            display: flex;\n            align-items: flex-start;\n            justify-content: flex-end;\n        }\n        .mark-badge {\n            background-color: #eee;\n            padding: 2px 6px;\n            border-radius: 4px;\n            border: 1px solid #ddd;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"page\">\n        <div class=\"content-wrapper\">\n            <div class=\"top-header\">\n                <div class=\"logo-area\">\n                    <img src=\"logo1.png\" alt=\"Logo\">\n                </div>\n            </div>\n            <div class=\"main-title-container\">\n                <div class=\"sub-title\">{SUBTITLE}</div>\n            </div>\n            <div class=\"meta-bar\">\n                <div class=\"meta-item\"><span class=\"meta-label\">Batch:</span> {BATCH}</div>\n                <div class=\"meta-divider\"></div>\n                <div class=\"meta-item\"><span class=\"meta-label\">Set:</span> {SET}</div>\n                <div class=\"meta-divider\"></div>\n                <div class=\"meta-item\"><span class=\"meta-label\">Date:</span> {DATE}</div>\n                <div class=\"meta-divider\"></div>\n                <div class=\"meta-item\"><span class=\"meta-label\">Duration:</span> {DURATION} Mins</div>\n                <div class=\"meta-divider\"></div>\n                <div class=\"meta-item\"><span class=\"meta-label\">Max Marks:</span> {MAX_MARKS}</div>\n            </div>\n            <!-- AI will generate sections and questions here -->\n        </div>\n    </div>\n</body>\n</html>",
    "is_customized": false
