    "html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<title>Question Paper (A5 Duplex Modern)</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&display=swap\" rel=\"stylesheet\">\n<script src=\"https://polyfill.io/v3/polyfill.min.js?features=es6\"></script>\n<script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js\"></script>\n<style>\n  @page {\n    size: A5;\n    margin: 8mm 8mm 10mm 8mm;\n  }\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  body {\n    font-family: system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n    background-color: #ffffff;\n    color: #1f2937;\n    padding: 0;\n    font-size: 11px;\n    line-height: 1.35;\n  }\n  .page {\n    width: 100%;\n  }\n  .modern-header {\n    border: 1px solid #111827;\n    padding: 6px 10px;\n    margin-bottom: 10px;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n  }\n  .org-title {\n    font-family: 'Space Mono', monospace;\n    font-size: 12px;\n    font-weight: 700;\n    color: #111827;\n  }\n  .paper-sub {\n    font-size: 11px;\n    font-weight: 600;\n    color: #4b5563;\n  }\n  .logo img {\n    height: 32px;\n  }\n  .meta-row {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 8px;\n    margin-bottom: 10px;\n    font-family: 'Space Mono', monospace;\n    font-size: 10px;\n  }\n  .meta-tag {\n    background-color: #f3f4f6;\n    border: 1px solid #e5e7eb;\n    padding: 2px 6px;\n    border-radius: 2px;\n  }\n  .meta-tag strong {\n    color: #111827;\n  }\n  .section-box {\n    border: 1px solid #e5e7eb;\n    margin-bottom: 10px;\n    border-radius: 4px;\n    overflow: hidden;\n  }\n  .section-bar {\n    background-color: #111827;\n    color: #ffffff;\n    padding: 4px 8px;\n    display: flex;\n    justify-content: space-between;\n    font-weight: 700;\n    font-size: 10.5px;\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n  }\n  .section-instruction {\n    font-size: 10px;\n    color: #6b7280;\n    padding: 4px 8px;\n    background-color: #f9fafb;\n    border-bottom: 1px solid #e5e7eb;\n    font-style: italic;\n  }\n  .q-row {\n    display: flex;\n    padding: 6px 8px;\n    border-bottom: 1px solid #f3f4f6;\n  }\n  .q-row:last-child {\n    border-bottom: none;\n  }\n  .q-num {\n    font-weight: 700;\n    width: 20px;\n  }\n  .q-text {\n    flex-grow: 1;\n    padding-right: 10px;\n  }\n  .q-marks {\n    font-weight: 600;\n    font-size: 10px;\n    color: #4b5563;\n    background-color: #f3f4f6;\n    padding: 1px 4px;\n    border-radius: 2px;\n    align-self: flex-start;\n  }\n  .footer {\n    position: fixed;\n    bottom: 0;\n    left: 0;\n    right: 0;\n    display: flex;\n    justify-content: space-between;\n    font-size: 8.5px;\n    font-family: 'Space Mono', monospace;\n    color: #9ca3af;\n    border-top: 1px solid #e5e7eb;\n    padding-top: 4px;\n  }\n</style>\n</head>\n<body>\n  <div class=\"page\">\n    <div class=\"modern-header\">\n      <div>\n        <div class=\"org-title\">AIMS EVALUATION SYSTEM</div>\n        <div class=\"paper-sub\">{SUBTITLE}</div>\n      </div>\n      <div class=\"logo\"><img src=\"logo1.png\" alt=\"Logo\"></div>\n    </div>\n    <div class=\"meta-row\">\n      <div class=\"meta-tag\">BATCH: <strong>{BATCH}</strong></div>\n      <div class=\"meta-tag\">SET: <strong>{SET}</strong></div>\n      <div class=\"meta-tag\">DATE: <strong>{DATE}</strong></div>\n      <div class=\"meta-tag\">TIME: <strong>{DURATION} Min</strong></div>\n      <div class=\"meta-tag\">MARKS: <strong>{MAX_MARKS}</strong></div>\n    </div>\n    <!-- AI will populate section content here -->\n    <div class=\"footer\">\n      <span>A5 DUPLEX MODERN</span>\n      <span>CONFIDENTIAL - DUPLEX</span>\n    </div>\n  </div>\n</body>\n</html>",
