/**
 * Dynamically parses aims/lib/screens/qp_templates.dart Dart source code to extract
 * all raw HTML string constants and QpTemplate definitions.
 */
export function parseDartTemplates(dartCode: string): QpTemplate[] {
  if (!dartCode || typeof dartCode !== 'string') {
    return DEFAULT_DART_TEMPLATES;
  }

  // 1. Extract raw string constants: const String _varName = r'''...''';
  const rawStrings: Record<string, string> = {};
  const rawRegex = /const\s+String\s+_(\w+)\s*=\s*r['"]{3}([\s\S]*?)['"]{3};/g;
  let match: RegExpExecArray | null;
  while ((match = rawRegex.exec(dartCode)) !== null) {
    rawStrings[match[1]] = match[2];
  }

  // 2. Extract template definitions in qpTemplates list
  const templateRegex = /QpTemplate\(\s*['"]([^'"]+)['"]\s*,\s*['"]([^'"]+)['"]\s*,\s*['"]([^'"]+)['"]\s*,\s*_(\w+)\s*,\s*_(\w+)\s*\)/g;
  const templates: QpTemplate[] = [];
  const foundIds = new Set<string>();

  while ((match = templateRegex.exec(dartCode)) !== null) {
    const [, tid, name, desc, htmlVar, sampleVar] = match;
    const htmlContent = rawStrings[htmlVar] || '';
    const sampleContent = rawStrings[sampleVar] || '';
    if (htmlContent) {
      templates.push({
        id: tid,
        name,
        description: desc,
        html: htmlContent,
        sample: sampleContent,
        defaultHtml: htmlContent,
        isActive: true,
      });
      foundIds.add(tid);
    }
  }

  // Also include known mappings if defined in Dart code but not listed in qpTemplates
  for (const [tid, name, desc, htmlVar, sampleVar] of ALL_KNOWN_DART_MAPPINGS) {
    if (!foundIds.has(tid) && rawStrings[htmlVar]) {
      templates.push({
        id: tid,
        name,
        description: desc,
        html: rawStrings[htmlVar] || '',
        sample: rawStrings[sampleVar] || '',
        defaultHtml: rawStrings[htmlVar] || '',
        isActive: true,
      });
      foundIds.add(tid);
    }
  }

  return templates.length > 0 ? templates : DEFAULT_DART_TEMPLATES;
}

export function getSavedTemplates(): QpTemplate[] {
  try {
    const raw = localStorage.getItem('qp_custom_templates');
    if (raw) {
      const customMap: Record<string, string> = JSON.parse(raw);
      return DEFAULT_DART_TEMPLATES.map(t => {
        if (customMap[t.id]) {
          return {
            ...t,
            html: customMap[t.id],
            isCustomized: true,
            defaultHtml: t.html
          };
        }
        return t;
      });
    }
  } catch (e) {
    console.error('Error loading custom templates:', e);
  }
  return DEFAULT_DART_TEMPLATES;
}

export function saveCustomTemplate(templateId: string, customHtml: string): void {
  try {
    const raw = localStorage.getItem('qp_custom_templates');
    const customMap: Record<string, string> = raw ? JSON.parse(raw) : {};
    customMap[templateId] = customHtml;
    localStorage.setItem('qp_custom_templates', JSON.stringify(customMap));
  } catch (e) {
    console.error('Error saving custom template:', e);
  }
}

export function resetCustomTemplate(templateId: string): void {
  try {
    const raw = localStorage.getItem('qp_custom_templates');
    if (raw) {
      const customMap: Record<string, string> = JSON.parse(raw);
      delete customMap[templateId];
      localStorage.setItem('qp_custom_templates', JSON.stringify(customMap));
    }
  } catch (e) {
    console.error('Error resetting custom template:', e);
  }
}

